    if not isinstance(p, str):
        return False
    if p == "":
        return False
    if p.startswith("/"):
        return False
    if "\\" in p:
        return False
    if any(is_control(c) for c in p):
        return False
    if len(p.encode("utf-8")) > 100:
        return False
    for comp in p.split("/"):
        if comp == "" or comp == "." or comp == "..":
            return False
    return True


