    if not isinstance(s, str):
        return False
    if len(s) % 4 != 0:
        return False
    try:
        return len(base64.b64decode(s.encode("ascii"), validate=True)) <= 64 * 1024
    except (binascii.Error, UnicodeEncodeError):
        return False


