        except Exception:
            return None
        total += len(content)
        if total > 128 * 1024:
            return None
        parsed.append((m["path"], content, mode))
    if total > 128 * 1024:
        return None
    parsed.sort(key=lambda t: t[0])
    return parsed


def tar_header(name_b, size, mode):
    h = bytearray()
    h += name_b.ljust(100, b"\x00")
    h += (format(mode, "07o") + "\0").encode().ljust(8, b"\x00")
    h += b"0000000\0"  # uid
    h += b"0000000\0"  # gid
    h += (format(size, "011o") + "\0").encode().ljust(12, b"\x00")
    h += b"00000000000\0"  # mtime
    h += b" " * 8  # checksum placeholder
    h += b"0"  # typeflag: regular file
    h += b"\x00" * 100  # linkname
    h += b"ustar\0" + b"00"  # magic + version
    h += b"\x00" * 32  # uname
    h += b"\x00" * 32  # gname
    h += b"\x00" * 8  # devmajor
    h += b"\x00" * 8  # devminor
    h += b"\x00" * 155  # prefix
    chk = sum(h)
    h[148:156] = (format(chk, "06o") + "\0").encode().ljust(8, b"\x00")
    assert len(h) == 512
    return bytes(h)


